import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { boardUrl, call, t, tx, ui } from './util';
/**
 * On a project's page (ernestdefoe/projects): its boards with their progress, for people who may
 * see them, and "Add a board" for the project's authors. Nothing at all when there's nothing to show.
 */
export default class ProjectBoards extends Component {
  boards = null;
  oninit(vnode) {
    super.oninit(vnode);
    call('GET', '/boards', undefined, {
      tab: 'all',
      project: this.attrs.project.id
    }, true).then(answer => this.boards = answer.boards).catch(() => this.boards = []).finally(() => m.redraw());
  }
  view() {
    const p = this.attrs.project;
    const me = app.session.user ? Number(app.session.user.id()) : 0;
    const author = !!me && (Number(p.author?.id) === me || (p.coAuthors || []).some(a => Number(a.id) === me));
    const canAdd = author && app.forum.attribute('corkboardCanCreate');
    if (!this.boards || !this.boards.length && !canAdd) return null;
    return m("section", {
      className: "CorkboardProjectBoards"
    }, m("h2", {
      className: "CorkboardProjectBoards-title"
    }, m(Icon, {
      name: "fas fa-table-columns"
    }), " ", t('project.title')), this.boards.map(b => {
      const pct = b.cardCount ? Math.round(b.doneCount / b.cardCount * 100) : 0;
      return m(Link, {
        className: "CorkboardProjectBoards-board",
        href: boardUrl(b),
        style: {
          '--board-color': b.color
        }
      }, m("span", {
        className: "CorkboardProjectBoards-name"
      }, b.title), m("span", {
        className: "CorkboardProgress",
        role: "progressbar",
        "aria-valuemin": "0",
        "aria-valuemax": "100",
        "aria-valuenow": pct,
        "aria-label": tx('list.progress', {
          done: b.doneCount,
          total: b.cardCount
        })
      }, m("span", {
        className: "CorkboardProgress-bar",
        style: {
          width: `${pct}%`
        }
      })), m("span", {
        className: "CorkboardProjectBoards-meta"
      }, t('list.progress', {
        done: b.doneCount,
        total: b.cardCount
      }), b.dueSoon ? m('[', null, " \xB7 ", t('list.due_soon', {
        count: b.dueSoon
      })) : null));
    }), canAdd ? m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => ui().then(({
        CreateBoardModal
      }) => app.modal.show(CreateBoardModal, {
        projectId: Number(p.id),
        template: 'simple'
      }))
    }, t('project.add')) : null);
  }
}