import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import { boardUrl, due, t, tx } from '../util';
import { fetchWidget } from './data';
const PRIORITY = {
  urgent: 'is-urgent',
  high: 'is-high',
  normal: 'is-normal',
  low: 'is-low'
};

/**
 * The three widgets, one component in every host. My cards and Due soon are the viewer's own
 * (guests get nothing: no box). Board progress shows one board to whoever may see it.
 */
export default class CorkboardWidget extends Component {
  view() {
    const {
      kind,
      settings = {},
      bare
    } = this.attrs;
    if (kind !== 'progress' && !app.session.user) return null;
    const body = kind === 'mine' ? this.mine(settings) : kind === 'due' ? this.due(settings) : this.progress(settings);
    if (body === null) return null;
    return m("div", {
      className: classList('CorkboardWidget', `CorkboardWidget--${kind}`, bare && 'CorkboardWidget--bare')
    }, bare ? null : m("h2", {
      className: "CorkboardWidget-title"
    }, m(Icon, {
      name: kind === 'mine' ? 'fas fa-id-card' : kind === 'due' ? 'fas fa-clock' : 'fas fa-bars-progress'
    }), " ", t(`widget.${kind}_title`)), body);
  }
  mine(s) {
    const {
      data,
      loading
    } = fetchWidget('/my-cards', {
      limit: Math.max(1, Math.min(10, Number(s.count) || 5)),
      owned: s.owned ? 1 : undefined
    });
    if (loading) return m(LoadingIndicator, {
      size: "small"
    });
    if (!data || data.error) return null;
    return [data.cards.length ? m("ul", {
      className: "CorkboardWidget-list"
    }, data.cards.map(c => this.row(c, `${c.board} · ${c.column}`))) : m("p", {
      className: "CorkboardWidget-empty"
    }, t('widget.mine_empty')), m(Link, {
      className: "CorkboardWidget-more",
      href: app.route('corkboard.mine')
    }, data.total > data.cards.length ? t('widget.see_all', {
      count: data.total
    }) : t('widget.open_mine'))];
  }
  due(s) {
    const board = String(s.board || '').replace(/\D/g, '');
    const {
      data,
      loading
    } = fetchWidget('/due-soon', {
      days: Number(s.days) || 3,
      limit: Math.max(1, Math.min(10, Number(s.count) || 5)),
      board: board || undefined
    });
    if (loading) return m(LoadingIndicator, {
      size: "small"
    });
    if (!data || data.error) return null;
    if (!data.cards.length) return m("p", {
      className: "CorkboardWidget-empty"
    }, t('widget.due_empty'));
    return m("ul", {
      className: "CorkboardWidget-list"
    }, data.cards.map(c => {
      const names = (c.assigneeIds || []).map(id => data.users[id]?.name).filter(Boolean);
      return this.row(c, [board ? '' : c.board, names.length ? names.join(', ') : ''].filter(Boolean).join(' · '));
    }));
  }
  progress(s) {
    const id = String(s.board || '').replace(/\D/g, '');
    if (!id) return app.session.user && app.forum.attribute('corkboardCanModerate') ? m("p", {
      className: "CorkboardWidget-empty"
    }, t('widget.progress_pick')) : null;
    const {
      data,
      loading
    } = fetchWidget(`/progress/${id}`, {});
    if (loading) return m(LoadingIndicator, {
      size: "small"
    });
    if (!data || data.error) return null;
    const total = data.columns.reduce((n, c) => n + c.count, 0);
    const done = data.columns.filter(c => c.isDone).reduce((n, c) => n + c.count, 0);
    return [m(Link, {
      className: "CorkboardWidget-board",
      href: boardUrl(data.board)
    }, data.board.title), m("div", {
      className: "CorkboardStack",
      role: "img",
      "aria-label": tx('list.progress', {
        done,
        total
      })
    }, data.columns.map((c, i) => c.count ? m("span", {
      className: classList('CorkboardStack-part', c.isDone && 'is-done'),
      style: {
        flexGrow: c.count,
        opacity: c.isDone ? 1 : 0.35 + 0.5 * i / Math.max(1, data.columns.length)
      },
      title: `${c.title}: ${c.count}`
    }) : null)), m("p", {
      className: "CorkboardWidget-summary"
    }, t('list.progress', {
      done,
      total
    })), m("ul", {
      className: "CorkboardWidget-legend"
    }, data.columns.map(c => m("li", null, c.title, " ", m("strong", null, c.count)))), s.next !== false && data.next.length ? m("ul", {
      className: "CorkboardWidget-list"
    }, data.next.map(c => this.row({
      ...c,
      boardId: data.board.id,
      boardSlug: data.board.slug
    }, null))) : null];
  }
  row(c, sub) {
    const when = due(c);
    return m("li", {
      className: "CorkboardWidget-item"
    }, m(Link, {
      href: boardUrl({
        id: c.boardId,
        slug: c.boardSlug
      }, c.id)
    }, m("span", {
      className: "CorkboardWidget-itemTitle"
    }, c.priority && c.priority !== 'none' ? m("span", {
      className: 'CorkboardPriority-dot ' + PRIORITY[c.priority]
    }) : null, c.title), m("span", {
      className: "CorkboardWidget-itemMeta"
    }, sub ? m("span", {
      className: "CorkboardWidget-where"
    }, sub) : null, when ? m("span", {
      className: 'CorkboardDue is-' + when.state
    }, when.text) : null)));
  }
}
flarum.reg.add('ernestdefoe-corkboard', 'forum/widgets/Widget', CorkboardWidget);